'use strict'

const { Query } = require('./query.js')

function Postgres () {
  const options = {
    database: 'postgres',
    host: ['localhost'],
    port: [5432],
    user: 'postgres',
  }

  async function handler (query) {
    return query
  }

  async function dispatch (query) {
    async function handler (query) {
      return query
    }

    return handler(query)
  }

  return [handler(new Query()), dispatch(new Query())]
}

module.exports = Postgres
